static Func<A, C> Compose<A, B, C>(this Func<A, B> f, Func<B, C> g) => x => g(f(x));

Func<string, string>  normalize = s => s.Trim().ToLowerInvariant();
Func<string, int>     length    = s => s.Length;

var normalizeThenMeasure = normalize.Compose(length);
int n = normalizeThenMeasure("  Hello  ");
